        what: `schedule cron is ${cron ? `"${cron}"` : '(none)'} — the contract requires "${STUB_CRON}"`,
        fix: `set the schedule trigger to - cron: "${STUB_CRON}" (or re-copy the orchestrator from the pack's stubs/workflows/)`,
