383	// The I/O half of the disposal: read the workflow runs for the open PR's head
384	// sha, decide with pullDisposition, and either merge it (last cycle's content is
385	// verified — the arm just never landed it) or close it and delete its branch so
386	// this cycle re-cuts from scratch. Returns the PR when it still stands (a `wait`,
387	// a `review` member, or a failed attempt), null when the way is clear.
388	//
389	// Best-effort throughout: anything unreadable or unmergeable leaves the PR as it
390	// found it, and the cycle skips rather than piling a second PR on top.
391	async function disposeOpenPull(token, repo, pr, delivery) {
392	  const { status, json } = await gh(token, `/repos/${repo}/actions/runs?head_sha=${pr.head?.sha}&per_page=100`);
393	  if (status !== 200) {
394	    console.log(`baselining: could not read the runs for PR #${pr.number}'s head (HTTP ${status})`);
395	    return pr;
396	  }
397	  const runs = (json?.workflow_runs ?? []).map((r) => ({ name: r.name, status: r.status, conclusion: r.conclusion }));
398	  const disposition = pullDisposition({ delivery, runs });
399	
400	  if (disposition === 'keep' || disposition === 'wait') {
401	    console.log(`baselining: keeping PR #${pr.number} (${disposition})`);
402	    return pr;
403	  }
404	
405	  if (disposition === 'merge') {
406	    const res = await gh(token, `/repos/${repo}/pulls/${pr.number}/merge`, {
407	      method: 'PUT', body: { merge_method: 'squash' },
408	    });
409	    if (res.status === 200) {
410	      console.log(`baselining: merged PR #${pr.number} — ${mergeReason(runs)}`);
411	      await deleteBranch({ token, repo, ref: pr.head?.ref, log: (s) => console.log(`baselining: ${s}`) });
412	      return null;
413	    }
414	    console.log(`baselining: could not merge PR #${pr.number} (${res.status}: ${res.json?.message ?? 'no message'})`
415	      + ' — closing it instead; the converge is idempotent and this cycle re-cuts it');
416	  }
417	
418	  // Closed, not left to rot: whatever went wrong on that head, the next converge
419	  // reproduces the same content from the same inputs. Named in the log because a
420	  // member closing its maintenance PR every single night is a repo whose CI needs
421	  // a human, and the pattern has to be visible to be noticed.
422	  const closed = await gh(token, `/repos/${repo}/pulls/${pr.number}`, { method: 'PATCH', body: { state: 'closed' } });
423	  if (closed.status !== 200) {
424	    console.log(`baselining: could not close PR #${pr.number} (${closed.status}) — leaving it and skipping this cycle`);
425	    return pr;
426	  }
427	  console.log(`baselining: closed PR #${pr.number} — it did not land (${failureSummary(runs)}); re-cutting this cycle`);
428	  await deleteBranch({ token, repo, ref: pr.head?.ref, log: (s) => console.log(`baselining: ${s}`) });
429	  return null;
430	}
