632	  //     this real repo against a canon BRANCH and asked whether the result still
633	  //     works — and now it must leave no trace: no commit, no branch, no PR, and
634	  //     above all no stamp. Stamping a branch head would leave the member
635	  //     `ref-not-on-trunk`, which the #328 anti-rewind guard then refuses to
636	  //     converge over: a rehearsal that wedged the repo it was rehearsing on.
637	  //     `git checkout -- .` restores the working tree wholesale, so the mount goes
638	  //     back to the vendored snapshot the repo actually runs.
639	  if (source.rehearsal) {
640	    git(['-C', root, 'checkout', '--', '.']);
641	    const verdict = selftest.ok && checks.ok ? 'PASS' : 'FAIL';
642	    console.log(`baselining: rehearsal ${verdict} — selftest ${selftest.ok ? 'ok' : 'FAILED'}, `
643	      + `checks ${checks.ok ? 'green' : 'RED'}, ${changed.length} file(s) would have changed. Working tree restored.`);
644	    if (verdict === 'FAIL') process.exit(1);   // the canary's whole purpose: fail the canon PR
645	    return;
646	  }
647	
648	  // 8. Deliver the converge (only when there's something to land).
649	  if (meaningfulChange || pending.length) {
650	    const seed = Math.random().toString(36).slice(2, 8);
651	    delivered = await deliver(root, repo, base, token, delivery, seed, withheld);
652	    console.log(`baselining: delivered converge on ${delivered.branch}${delivered.pr ? ` (PR #${delivered.pr}${delivered.merged ? ', merged' : ''})` : ''} (${delivery})`);
653	  } else {
654	    console.log('baselining: no change to deliver');
655	  }
656	
657	  // 9. Request the agent only when judgment is left (conditional handoff, §3) — naming
658	  //    what this run created AND why the agent is being woken. `delivered` stays null
659	  //    when nothing was opened, and the issue then names nothing; `reason` is non-null
660	  //    exactly when the agent is requested at all.
661	  if (requestAgent && requestFile) {
662	    writeFileSync(requestFile, `${JSON.stringify({ marker: AGENT_REQUEST_MARKER, delivered, reason })}\n`);
663	  }
664	  console.log(requestAgent
665	    ? `baselining: requested agent stage (${reason.code}: ${reason.detail})`
666	    : 'baselining: agentless night — deterministic converge delivered, no agent needed');
667	}
668	
669	// Run only when invoked directly (the scheduler's `node worker.mjs`), never on
670	// import — a test imports the pure helpers without any git or network.
671	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
672	  main().catch((e) => { console.error(`baselining preprocessing failed: ${e.message}`); process.exit(1); });
673	}
674

